func connect(root *Node) *Node {
	if root == nil || root.Left == nil {
		return root
	}
	root.Left.Next = root.Right
	if root.Next != nil {
		root.Right.Next = root.Next.Left
	}
	connect(root.Left)
	connect(root.Right)
	return root
}

class Node {
  public int val;
  public Node left;
  public Node right;
  public Node next;

  public Node() {
  }

  public Node(int _val) {
    val = _val;
  }

  public Node(int _val, Node _left, Node _right, Node _next) {
    val = _val;
    left = _left;
    right = _right;
    next = _next;
  }
}

class Solution {
  public Node connect(Node root) {
    if (root == null || root.left == null) {
      return root;
    }
    root.left.next = root.right;
    if (root.next != null) {
      root.right.next = root.next.left;
    }
    connect(root.left);
    connect(root.right);
    return root;
  }
}

class Solution:
    def connect(self, root: "Node") -> "Node":
        if root is None or root.left is None:
            return root
        root.left.next = root.right
        if root.next is not None:
            root.right.next = root.next.left
        self.connect(root.left)
        self.connect(root.right)
        return root

impl Solution {
  unsafe fn connect_ptr(node: *mut Node) {
    if node.is_null() {
      return;
    }
    let n = &mut *node;
    if n.left.is_none() {
      return;
    }
    let left = n.left.as_mut().unwrap().as_mut() as *mut Node;
    let right = n.right.as_mut().unwrap().as_mut() as *mut Node;
    (*left).next = right;
    let next_ptr = n.next;
    if !next_ptr.is_null() {
      let sibling = &mut *next_ptr;
      if let Some(sl) = sibling.left.as_mut() {
        (*right).next = sl.as_mut() as *mut Node;
      }
    }
    Self::connect_ptr(left);
    Self::connect_ptr(right);
  }

  pub fn connect(root: Option<Box<Node>>) -> Option<Box<Node>> {
    let mut root = root;
    if let Some(r) = root.as_mut() {
      unsafe {
        Solution::connect_ptr(r.as_mut() as *mut Node);
      }
    }
    root
  }
}

const connect = (root: Node | null): Node | null => {
  if (!root || !root.left) return root;
  root.left.next = root.right;
  if (root.next) root.right!.next = root.next.left;
  connect(root.left);
  connect(root.right);
  return root;
};
